{%- doc -%}
  Video placeholder styles. Kept in a standalone snippet so they can be rendered
  into dynamically-injected contexts (the quick-add modal) as well as on normal pages.

  @example
  {% render 'video-placeholder-styles' %}
{%- enddoc -%}

{% stylesheet %}
  .video-placeholder-wrapper {
    position: relative;
    width: 100%;
    height: 100%;
    aspect-ratio: var(--size-style-aspect-ratio, auto);
  }

  :not(deferred-media) > .video-placeholder-wrapper {
    width: var(--video-placeholder-width);
  }

  .video-placeholder-wrapper > * {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
  }

  .video-placeholder-wrapper.border-style {
    /* Apply the border radius to the video */
    overflow: hidden;
  }

  .video-placeholder-wrapper__poster-icon {
    position: absolute;
    top: 50%;
    left: 50%; /* stylelint-disable-line csstools/use-logical -- centring pair with a physical translate(-50%) */
    transform: translate(-50%, -50%);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .video-placeholder-wrapper__poster-icon svg {
    width: var(--button-size);
    height: var(--button-size);
    color: var(--color-white);
    filter: drop-shadow(var(--shadow-button));

    &:hover {
      color: rgb(var(--color-white-rgb) / var(--opacity-80));
    }

    @media screen and (min-width: 750px) {
      width: 4rem;
      height: 4rem;
    }
  }
{% endstylesheet %}

{%- doc -%}
  Renders a video element, from a video object (<video> element) or a video URL (<iframe> element)

  Shared parameters:

  @param {boolean} [video_autoplay] - Whether the video should autoplay
  @param {boolean} [video_loop] - Whether the video should loop
  @param {string} [video_class] - Additional classes for the video element
  @param {string} [video_style] - Additional inline styles
  @param {object} [video_preview_image] - Preview image to show before video plays
  @param {string} [widths] - Responsive widths
  @param {string} [sizes] - Responsive sizes
  @param {string} [loading] - Loading attribute
  @param {string} [additional_attributes] - Any additional HTML attributes
  @param {string} [video_type] - 'youtube' or 'vimeo'
  @param {boolean} [disable_controls] - Whether to disable controls. If true, only play/pause will be usable.
  @param {object} video - The Shopify video object or a string containing a YouTube ID or Vimeo ID
  @param {object} [block] - The block object

  Video from URL:

  @param {boolean} [video_from_url] - Set to true to use a video from URL instead of a Shopify video object
  @param {string} [video_alt] - The video alt text

  @example
  {% render 'video', video: section.settings.video, video_autoplay: true, video_loop: true %}
{%- enddoc -%}

{% liquid
  assign block_settings = block.settings
  assign video_alt = video_alt | default: video.alt
  assign alt = 'blocks.load_video' | t: description: video_alt | escape
  assign video_preview_image = video_preview_image | default: video.preview_image
  assign video_autoplay = video_autoplay | default: block_settings.video_autoplay
  assign video_loop = video_loop | default: block_settings.video_loop
  assign media_width_desktop = 100 | divided_by: 2 | append: 'vw'
  assign media_width_mobile = '100vw'
  assign sizes = '(min-width: 750px) ' | append: media_width_desktop | append: ', ' | append: media_width_mobile
  assign widths = '240, 352, 832, 1200, 1600, 1920, 2560, 3840'
%}

{% if video_from_url %}
  {% liquid
    if video_type == 'youtube'
      assign video_src = 'https://www.youtube.com/embed/VIDEO_ID?' | replace: 'VIDEO_ID', video

      if video_autoplay == false and video_preview_image != blank
        assign video_src = video_src | append: '&autoplay=1'
      endif

      if video_autoplay
        assign video_src = video_src | append: '&autoplay=1&mute=1'
      endif

      if video_loop
        assign video_src = video_src | append: '&playlist=' | append: video | append: '&loop=1'
      endif
      if disable_controls
        assign video_src = video_src | append: '&controls=0'
        assign video_src = video_src | append: '&enablejsapi=1'
      endif
      assign class = 'js-youtube'
    else
      assign video_src = 'https://player.vimeo.com/video/VIDEO_ID?' | replace: 'VIDEO_ID', video

      if video_autoplay == false and video_preview_image != blank
        assign video_src = video_src | append: '&autoplay=1'
      endif

      if video_autoplay
        assign video_src = video_src | append: '&autoplay=1&muted=1'
      endif
      if video_loop
        assign video_src = video_src | append: '&loop=1'
      endif
      if disable_controls
        assign video_src = video_src | append: '&controls=0'
        assign video_src = video_src | append: '&api=1'
      endif
      assign class = 'js-vimeo'
    endif
  %}
  {% capture video_iframe %}
      <iframe
        src="{{ video_src }}"
        class="{{ class }}"
        allow="autoplay; encrypted-media"
        allowfullscreen
        title="{{ video_alt | escape }}"
      ></iframe>
  {% endcapture %}
{% else %}
  {% liquid
    if disable_controls
      assign controls = false
      assign enable_js_api = true
    else
      assign controls = true
      assign enable_js_api = false
    endif
  %}

  {% capture video_tag %}
    {% if video.host == 'youtube' %}
      {{
        video
        | external_video_url: autoplay: true, loop: video_loop, playlist: video.external_id, mute: '1', controls: controls, enablejsapi: enable_js_api
        | external_video_tag: data-video-type: 'youtube'
      }}
    {% elsif video.host == 'vimeo' %}
      {{
        video
        | external_video_url: autoplay: true, loop: video_loop, muted: '1', controls: controls, api: enable_js_api
        | external_video_tag: data-video-type: 'vimeo'
      }}
    {% else %}
      {{ video | video_tag: image_size: '2500x', autoplay: true, loop: video_loop, muted: true, controls: controls }}
    {% endif %}
  {% endcapture %}
{% endif %}

{% if video != blank %}
  <deferred-media
    class="{{ video_class }}"
    style="{{ video_style }}"
    {% if video_autoplay %}
      autoplay
    {% endif %}
    {{ additional_attributes }}
  >
    {% if video_preview_image != blank %}
      <button
        class="button deferred-media__poster-button button-unstyled"
        ref="deferredMediaPlayButton"
        aria-label="{{ alt }}"
        type="button"
        on:click="/showDeferredMedia"
        style="--video-aspect-ratio: {{ video.aspect_ratio }}"
      >
        {{
          video_preview_image
          | image_url: width: 3840
          | image_tag: widths: widths, sizes: sizes, loading: loading, class: 'deferred-media__poster-image'
        }}

        <span class="deferred-media__poster-icon icon-play">
          <span class="visually-hidden">{{ 'accessibility.play_video' | t }}</span>
          {{- 'icon-play.svg' | inline_asset_content -}}
        </span>
      </button>
    {% endif %}

    {% if disable_controls %}
      <button
        class="button button-unstyled deferred-media__poster-button video-interaction-hint hidden"
        ref="toggleMediaButton"
        type="button"
        on:click="/toggleMedia"
      >
        <span class="deferred-media__poster-icon icon-play hidden">
          <span class="visually-hidden">{{ 'accessibility.play_video' | t }}</span>
          {{- 'icon-play.svg' | inline_asset_content -}}
        </span>
        <span class="deferred-media__poster-icon icon-pause hidden">
          <span class="visually-hidden">{{ 'accessibility.pause_video' | t }}</span>
          {{- 'icon-pause.svg' | inline_asset_content -}}
        </span>
      </button>
    {% endif %}

    <template>
      {% if video_from_url %}
        {{ video_iframe }}
      {% else %}
        {{ video_tag }}
      {% endif %}
    </template>

    {% if video_autoplay or video_preview_image == blank %}
      {% if video_from_url %}
        {{ video_iframe }}
      {% else %}
        {{ video_tag }}
      {% endif %}
    {% endif %}
  </deferred-media>
{% else %}
  <div
    {{ additional_attributes }}
    class="{%- if video_class -%}{{ video_class }} {%- endif -%}video-placeholder-wrapper"
    style="{%- if video_style -%}{{ video_style }} {%- endif -%}--video-placeholder-width: {{ block_settings.custom_width | default: 100 }}%;"
  >
    {% if video_preview_image != blank and video_autoplay == false %}
      {{ video_preview_image | image_url: width: 3840 | image_tag: widths: widths, sizes: sizes, loading: loading }}
    {% else %}
      {{ 'hero-apparel-3' | placeholder_svg_tag }}
    {% endif %}
    <span class="video-placeholder-wrapper__poster-icon icon-play">
      <span class="visually-hidden">{{ 'accessibility.play_video' | t }}</span>
      {{- 'icon-play.svg' | inline_asset_content -}}
    </span>
  </div>
{% endif %}

{% render 'video-placeholder-styles' %}
{% render 'deferred-media-video-styles' %}

{% comment %}
  Opts into cross-document (MPA) view transitions and holds first paint until #MainContent
  parses, so the transition runs consistently. Emitted per-layout because assets/base.css is
  shared and can't read theme settings.

  view-transitions.js drops the blocker again whenever no transition can actually run, and
  falls back to dropping it at 1800 ms. It is gated on the same settings (snippets/scripts.liquid).
{% endcomment %}
{% if settings.transition_to_main_product or settings.page_transition_enabled %}
  {% style %}
    @media (prefers-reduced-motion: no-preference) {
      @view-transition {
        navigation: auto;
      }
    }
  {% endstyle %}
  <link
    rel="expect"
    href="#MainContent"
    blocking="render"
    id="view-transition-render-blocker"
  >
{% endif %}

{% doc %}
  Renders volume pricing information with quantity rules in a popover.
  Only renders if variant has quantity rules or volume pricing.

  @param {variant} variant - The variant object to display pricing for
  @param {string} [unique_id] - Optional unique identifier to append to popover ID (e.g., cart line index)
  @param {number} [quantity] - The current quantity (for highlighting active tier)
  @param {boolean} [show_label] - Shows label "Volume Pricing Available"

  @example
  {% render 'volume-pricing-info',
    variant: item.variant,
    unique_id: item.index,
    quantity: item.quantity
  %}
{% enddoc %}

{%- liquid
  assign has_quantity_rules = false
  if variant.quantity_rule.min > 1 or variant.quantity_rule.increment > 1 or variant.quantity_rule.max != null
    assign has_quantity_rules = true
  endif

  assign has_volume_pricing = false
  if variant.quantity_price_breaks.size > 0
    assign has_volume_pricing = true
  endif

  assign current_quantity = quantity | default: variant.quantity_rule.min | default: 1
-%}

{%- if has_quantity_rules or has_volume_pricing -%}
  {%- liquid
    assign popover_id = 'VolumePricingInfo-' | append: variant.id
    assign anchor_name = '--volume-pricing-trigger-' | append: variant.id

    assign use_currency = false
    if unique_id != blank
      assign popover_id = popover_id | append: '-' | append: unique_id
      assign anchor_name = anchor_name | append: '-' | append: unique_id
      if settings.currency_code_enabled_cart_items
        assign use_currency = true
      endif
    else
      if settings.currency_code_enabled_product_pages
        assign use_currency = true
      endif
    endif
  -%}
  <anchored-popover-component
    data-hover-triggered="true"
    class="volume-pricing-info"
    id="volume-pricing-anchor-{{ popover_id }}"
  >
    <button
      type="button"
      class="volume-pricing-info__button button-unstyled{% if show_label %} volume-pricing-info__button--with-label{% endif %}"
      aria-label="{{ 'accessibility.view_pricing_info' | t }}"
      ref="trigger"
      popovertarget="{{ popover_id }}"
      style="anchor-name: {{ anchor_name }};"
    >
      <span class="svg-wrapper">{{- 'icon-info.svg' | inline_asset_content -}}</span>
      {% if show_label %}
        {{ 'content.volume_pricing_available' | t }}
      {% endif %}
    </button>

    <div
      id="{{ popover_id }}"
      class="volume-pricing-info__popover"
      ref="popover"
      popover="auto"
      style="position-anchor: {{ anchor_name }};"
    >
      <volume-pricing-info>
        {%- if has_quantity_rules -%}
          <div class="volume-pricing-info__rules">
            {%- if variant.quantity_rule.increment > 1 -%}
              <span>{{ 'products.product.quantity_increments' | t: increment: variant.quantity_rule.increment }}</span>
            {%- endif -%}
            {%- if variant.quantity_rule.min > 1 or variant.quantity_rule.max != null -%}
              <span>
                {{- 'products.product.quantity_minimum' | t: minimum: variant.quantity_rule.min | default: 1 -}}
                {%- if variant.quantity_rule.max != null %}
                  • {{ 'products.product.quantity_maximum' | t: maximum: variant.quantity_rule.max -}}
                {%- endif -%}
              </span>
            {%- endif -%}
          </div>
        {%- endif -%}

        {%- if has_volume_pricing -%}
          <div class="volume-pricing-info__table">
            {%- assign min_qty = variant.quantity_rule.min | default: 1 -%}
            {%- assign first_break = variant.quantity_price_breaks.first.minimum_quantity -%}

            <div
              class="volume-pricing-info__row{% if current_quantity >= min_qty and current_quantity < first_break %} volume-pricing-info__row--active{% endif %}"
              data-quantity="{{ min_qty }}"
            >
              <span class="volume-pricing-info__quantity">{{ min_qty }}+</span>
              {%- capture price_text -%}{%- if use_currency -%}<bdi>{{ variant.price | money_with_currency | strip }}</bdi>/{{ 'content.each_abbreviation' | t }}{%- else -%}<bdi>{{ variant.price | money | strip }}</bdi>/{{ 'content.each_abbreviation' | t }}{%- endif -%}{%- endcapture -%}
              <span class="volume-pricing-info__price"
                ><span class="volume-pricing-info__checkmark">{{- 'icon-checkmark.svg' | inline_asset_content -}}</span>
                {{- price_text | strip -}}
              </span>
            </div>

            {%- for price_break in variant.quantity_price_breaks -%}
              {%- assign next_tier = variant.quantity_price_breaks[forloop.index].minimum_quantity -%}
              {%- assign is_last = forloop.last -%}
              {%- assign is_active = false -%}
              {%- if is_last -%}
                {%- if current_quantity >= price_break.minimum_quantity -%}
                  {%- assign is_active = true -%}
                {%- endif -%}
              {%- elsif current_quantity >= price_break.minimum_quantity and current_quantity < next_tier -%}
                {%- assign is_active = true -%}
              {%- endif -%}

              <div
                class="volume-pricing-info__row{% if is_active %} volume-pricing-info__row--active{% endif %}"
                data-quantity="{{ price_break.minimum_quantity }}"
              >
                <span class="volume-pricing-info__quantity">{{ price_break.minimum_quantity }}+</span>
                {%- capture price_text -%}{%- if use_currency -%}<bdi>{{ price_break.price | money_with_currency | strip }}</bdi>/{{ 'content.each_abbreviation' | t }}{%- else -%}<bdi>{{ price_break.price | money | strip }}</bdi>/{{ 'content.each_abbreviation' | t }}{%- endif -%}{%- endcapture -%}
                <span class="volume-pricing-info__price"
                  ><span class="volume-pricing-info__checkmark">
                    {{- 'icon-checkmark.svg' | inline_asset_content -}}
                  </span>
                  {{- price_text | strip -}}
                </span>
              </div>
            {%- endfor -%}
          </div>
        {%- endif -%}
      </volume-pricing-info>
    </div>
  </anchored-popover-component>
{%- endif -%}

{% stylesheet %}
  .volume-pricing-info {
    display: inline-flex;
  }

  .volume-pricing-info__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--minimum-touch-target);
    height: var(--minimum-touch-target);
    color: var(--color-foreground-secondary);
    cursor: pointer;
    transition: color var(--animation-speed) var(--animation-easing);
    flex-shrink: 0;
  }

  .volume-pricing-info__button:hover {
    color: var(--color-foreground);
  }

  .volume-pricing-info__button .svg-wrapper {
    width: var(--icon-size-sm);
    height: var(--icon-size-sm);
  }

  .volume-pricing-info__button--with-label {
    width: auto;
    gap: var(--gap-sm);
  }

  .volume-pricing-info__popover {
    --volume-pricing-popover-max-width: 320px;
    --volume-pricing-popover-spacing: 8px;
    --volume-pricing-popover-viewport-margin: 16px;

    min-inline-size: 280px;
    max-inline-size: var(--volume-pricing-popover-max-width);
    background: var(--color-background);
    border: var(--style-border-popover);
    border-radius: var(--style-border-radius-popover, 0);
    box-shadow: var(--shadow-popover);
    overflow: hidden;
    padding: 0;
    margin: 0;
    transition-property: display, opacity, translate;
    transition-duration: 0.3s;
    transition-timing-function: var(--ease-out-quad);
    transition-behavior: allow-discrete;
    translate: 0 20px;
    opacity: 0;
  }

  /* Native anchor positioning for supported browsers */
  .volume-pricing-info__popover {
    inset: unset;
    top: calc(anchor(bottom) + var(--volume-pricing-popover-spacing));
    inset-inline-start: anchor(start);
  }

  @supports (position-try-fallbacks: --top-left) {
    .volume-pricing-info__popover {
      position-try-fallbacks: --top-left;
    }

    @position-try --top-left {
      top: calc(anchor(top) - var(--volume-pricing-popover-spacing));
      bottom: auto;
      transform: translateY(-100%);
    }
  }

  /* Fallback positioning using custom properties */
  @supports not (position-anchor: --volume-pricing-trigger) {
    .volume-pricing-info__popover {
      position: fixed;
      top: calc(var(--anchor-bottom) * 1px + var(--volume-pricing-popover-spacing));
      inset-inline-start: max(
        var(--volume-pricing-popover-viewport-margin),
        min(
          var(--anchor-inline-start) * 1px,
          100vw - var(--volume-pricing-popover-max-width) - var(--volume-pricing-popover-viewport-margin)
        )
      );
    }
  }

  .volume-pricing-info__popover:popover-open {
    translate: 0 0;
    opacity: 1;
  }

  @starting-style {
    .volume-pricing-info__popover:popover-open {
      translate: 0 20px;
      opacity: 0;
    }
  }

  .volume-pricing-info__rules {
    display: flex;
    flex-direction: column;
    gap: var(--gap-2xs);
    padding: var(--padding-md);
    font-size: var(--font-size--xs);
  }

  .volume-pricing-info__rules,
  .volume-pricing-info__rules > span {
    color: rgb(var(--color-rgb, var(--color-foreground-rgb)) / var(--opacity-subdued-text));
  }

  .volume-pricing-info__table {
    display: flex;
    flex-direction: column;
  }

  .volume-pricing-info__row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--padding-sm) var(--padding-md);
    font-size: var(--font-size--sm);
    background: var(--color-background);
    border-inline-start: 3px solid transparent;
    transition: border-color var(--animation-speed) var(--animation-easing);
  }

  .volume-pricing-info__row:nth-child(odd) {
    background: rgb(var(--color-foreground-rgb) / var(--opacity-5));
  }

  .volume-pricing-info__row--active {
    border-inline-start-color: var(--color-foreground);
    font-weight: var(--font-weight-medium);
  }

  .volume-pricing-info__quantity {
    color: var(--color-foreground);
  }

  .volume-pricing-info__price {
    display: flex;
    align-items: center;
    color: var(--color-foreground);
  }

  .volume-pricing-info__checkmark {
    display: none;
    width: var(--icon-size-sm);
    height: var(--icon-size-sm);
    color: var(--color-foreground);
  }

  .volume-pricing-info__row--active .volume-pricing-info__checkmark {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
{% endstylesheet %}
